    private static void Check(bool v,string reason=""){if(!v)throw new Exception("M6.8-C1 authoring: "+reason);}
    private static void Reject(Action a){try{a();}catch(Exception e)when(e is ArgumentException or InvalidOperationException or IOException or JsonException){return;}throw new Exception("Invalid Montage authoring accepted.");}
    private static JsonElement Creation(AnimationGraphDefinition d,Guid clip)
    {
        Guid slot=Guid.NewGuid(),section=Guid.NewGuid();var m=new AnimationMontageDefinition(1,Guid.NewGuid(),"Reviewed action",d.SkeletonId,[new(slot,"Body",section,10,true,false,.1,.1)],[new(section,"Attack",slot,clip,0,.2,Guid.Empty)]);
        var node=AnimationGraphNode.Create(Guid.NewGuid(),"Body Slot",AnimationNodeKind.Slot) with{SlotId=slot,PlayOnStart=false};var output=d.Nodes.Single(n=>n.Kind==AnimationNodeKind.Output);var edge=d.Links.Single(l=>l.To==output.Id);
        return AnimationGraphEdits.Operations(new{op="montage.upsert",montage=m},new{op="node.upsert",node},new{op="link.delete",id=edge.Id},new{op="link.upsert",link=new AnimationGraphLink(Guid.NewGuid(),edge.From,edge.FromPin,node.Id,"pose")},new{op="link.upsert",link=new AnimationGraphLink(Guid.NewGuid(),node.Id,"pose",output.Id,"pose")});
    }
    private static void Click(GraphInspectionTests.Fixture f,ulong high,ulong low,double value=0){f.Click(high,low,value);f.Build();}
    private static void Refresh(GraphInspectionTests.Fixture f){f.View.SynchronizeGraph();f.Build();}
    private static void Text(GraphInspectionTests.Fixture f,ulong high,ulong low,string text,uint phase=3){byte[] bytes=Encoding.UTF8.GetBytes(text);var e=f.Event(high,low);e.Phase=phase;e.TextLength=(uint)bytes.Length;f.View.Apply([e],bytes);f.Build();}
    private static void Enter(GraphInspectionTests.Fixture f){f.ApproveUi();Click(f,40,8);Click(f,24,12);Click(f,24,48);Click(f,50,6,1);Click(f,50,7);Click(f,50,8);}
    private static void Ready(GraphInspectionTests.Fixture f){Click(f,50,10);Click(f,50,52,1);Click(f,50,53);}
