            using var f=new GraphInspectionTests.Fixture(output,repository,true);var w=f.Writer!;Guid id=Guid.NewGuid();object input=new{graphId=f.Graph,proposalId=id,operations=Creation(w.Capture()!,f.Clip)};
            Check(f.Call(AnimationGraphAuthoringSchemas.Propose,input,Guid.NewGuid()).GetProperty("isError").GetBoolean());f.ApproveUi();byte[] before=File.ReadAllBytes(f.File),scene=f.Owner.Document.CaptureBytes();
            using(var locked=new FileStream(f.File,FileMode.Open,FileAccess.Read,FileShare.None)){var p=f.Call(AnimationGraphAuthoringSchemas.Propose,input,Guid.NewGuid());Check(!p.GetProperty("isError").GetBoolean(),p.GetRawText());var result=p.GetProperty("structuredContent");CharacterInspectionTests.Schema(result,AnimationGraphAuthoringSchemas.Descriptor.OutputSchema);var diff=result.GetProperty("data");Check(diff.GetProperty("added").GetInt32()==6&&diff.GetProperty("removed").GetInt32()==1&&diff.GetProperty("updated").GetInt32()==0,"Montage/Slot/Section are separate reviewed rows");}
            Check(before.SequenceEqual(File.ReadAllBytes(f.File))&&f.Owner.Edit!.State.UndoCount==0&&scene.SequenceEqual(f.Owner.Document.CaptureBytes()));Guid request=Guid.NewGuid();ulong revision=f.Owner.Edit!.Revision;var tx=new{proposalId=id,expectedAssetRevision=f.Owner.Assets!.Clock.Revision};
            Check(f.Call(AnimationGraphCommands.CapabilityName,tx,request,revision).GetProperty("isError").GetBoolean());var controller=new EditorAuthorizationController(f.Workspace);var page=controller.Capture()!;var pending=page.Proposals.Single();controller.Approve(page,pending.Scope.Id,pending.Fingerprint,true,null);
