            Click(f,50,11);Check(w.Capture()!.Montage is null&&before.SequenceEqual(File.ReadAllBytes(f.File)));Click(f,50,12);Check(w.Capture()!.Montage!.Sections.Length==2&&f.Owner.Document.World.Tick==0);
        });
        yield return("M6.8-C1 typed proposal TTL/revoke/queued/re-pair and actual NCA interval/generation rejection",()=>{
            using var f=new GraphInspectionTests.Fixture(output,repository,true);var w=f.Writer!;f.ApproveUi();byte[] before=File.ReadAllBytes(f.File);var ops=Creation(w.Capture()!,f.Clip);Guid id=Guid.NewGuid();
            object Input(Guid p)=>new{graphId=f.Graph,proposalId=p,operations=ops};Check(!f.Call(AnimationGraphAuthoringSchemas.Propose,Input(id),Guid.NewGuid()).GetProperty("isError").GetBoolean());var review=w.CaptureReview(id);w.Approve(review,review.Fingerprint,review.Graph,true);f.Time.Now=60000;Reject(()=>w.CaptureReview(id));f.Time.Now=0;w.Reads.Revoke();Reject(()=>w.CaptureReview(id));w.CancelProposal(id);f.ApproveUi();id=Guid.NewGuid();Check(!f.Call(AnimationGraphAuthoringSchemas.Propose,Input(id),Guid.NewGuid()).GetProperty("isError").GetBoolean());review=w.CaptureReview(id);var endpoint=f.Owner.Endpoint!;var connection=endpoint.View.Connections.Single().ConnectionId;endpoint.Revoke(connection);endpoint.Pair(connection,true);Reject(()=>w.Approve(review,review.Fingerprint,review.Graph,true));w.CancelProposal(id);f.ApproveUi();
            var message=new{jsonrpc="2.0",id=789123,method="tools/call",@params=new{name=AnimationGraphAuthoringSchemas.Propose,arguments=new{contractVersion=2,requestId=Guid.NewGuid(),sessionId=f.Owner.Edit!.SessionId,expectedRevision=f.Owner.Edit.Revision,input=Input(Guid.NewGuid())}}};
            f.Client.StandardInput.WriteLine(JsonSerializer.Serialize(message,Wire.Json));f.Client.StandardInput.Flush();var response=f.Client.StandardOutput.ReadLineAsync();var watch=Stopwatch.StartNew();while(endpoint.View.QueueCount==0){if(watch.ElapsedMilliseconds>10000)throw new TimeoutException("Montage proposal queue");Thread.Sleep(1);}Check(!response.IsCompleted);w.Reads.Revoke();endpoint.Pump();Check(response.Wait(10000));using(var parsed=JsonDocument.Parse(response.Result!))Check(parsed.RootElement.GetProperty("result").GetProperty("isError").GetBoolean());Check(before.SequenceEqual(File.ReadAllBytes(f.File))&&w.Pending.Length==0&&f.Owner.Edit.State.UndoCount==0);
            w.ApproveFileWrite(w.Stamp,w.Path!,f.Graph,true);w.Begin(w.Stamp);w.ApplyDraft(ops);var section=w.Capture()!.Montage!.Sections.Single();w.ApplyDraft(AnimationGraphEdits.Operations(new{op="montage.section.upsert",section=section with{End=600}}));id=w.PrepareLocal();Reject(()=>w.CaptureReview(id));Check(before.SequenceEqual(File.ReadAllBytes(f.File)));w.Cancel();w.Begin(w.Stamp);w.ApplyDraft(ops);id=w.PrepareLocal();review=w.CaptureReview(id);w.Approve(review,review.Fingerprint,review.Graph,true);
